import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/README.md","filePath":"zh/root/README.md"}'),o={name:"zh/root/README.md"};function r(d,e,l,i,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<div align="center"><h1 id="open-cube-os" tabindex="-1">Open Cube OS <a class="header-anchor" href="#open-cube-os" aria-label="Permalink to &quot;Open Cube OS&quot;">​</a></h1><p><strong>一个从零写起的 x86_64 内核，附带 WinRE 风格的恢复 Shell。</strong></p><p><code>oc&gt;</code> 是提示符。一切皆可扩展。</p><p><a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">官网</a> · <a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">文档</a> · <a href="#downloads">下载</a> · <a href="./BUILDING.html">构建</a> · <a href="./ARCHITECTURE.html">架构</a> · <a href="./INTERFACES.html">接口参考</a></p></div><hr><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Open Cube OS 是 <strong>L0</strong>：一个完整的、自包含的 64 位内核，可在真实硬件和 QEMU 中启动，并为你提供一个包含 <strong>233 条命令</strong>的恢复 Shell 提示符（<code>oc&gt;</code>），用于检查和控制机器。</p><ul><li><strong>不是 Linux 的分支。</strong> 140,672 行原创 C/汇编代码，遵循 Apache 2.0 许可（验证：见下方的 <em>统计</em>）。</li><li><strong>能在 PC 平台的所有地方启动：</strong> 混合 BIOS + UEFI ISO，512 MiB RAM 即可流畅运行，磁盘为可选。</li><li><strong>一个真正的内核：</strong> 抢占式调度器、4 级分页、ring-3 用户程序与 53 个系统调用、FAT32/exFAT/ext4/ramfs 上的 VFS、包含 TLS 1.2/1.3 和 SSH（客户端 <em>和</em> 服务器）的完整 TCP/IP 协议栈、从 NVMe 到 xHCI 再到 ACPI AML 的 16 个驱动家族、崩溃转储、硬件看门狗（Intel TCO / ACPI WDAT）、OTA A/B 更新。</li><li><strong>按设计实现的恢复 Shell：</strong> 系统 <em>就是</em> WinRE 风格的环境——启动、诊断、修复、安装、更新。</li></ul><p>双层架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  Open Cube OS        kernel + oc&gt; recovery shell     &lt;- this repo</span></span>
<span class="line"><span>L1  upper extensions    built on the 162-interface surface</span></span></code></pre></div><p>L1 不随 L0 一起发布；扩展接口面 (<a href="./INTERFACES.html">INTERFACES.md</a>) 是契约，而共享对象加载器使 L1 模块可在运行时加载。</p><h2 id="主要亮点" tabindex="-1">主要亮点 <a class="header-anchor" href="#主要亮点" aria-label="Permalink to &quot;主要亮点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>提供的功能</th></tr></thead><tbody><tr><td>启动</td><td>GRUB 2.12 混合 ISO（BIOS El Torito + UEFI 镜像），multiboot2，内核作为 <code>self</code> 模块附加，A/B 槽位菜单</td></tr><tr><td>内存</td><td>基于 multiboot2 映射的 PMM 位图，4 级 VMM，支持通过 #PF 实际增长的 kmalloc 堆</td></tr><tr><td>CPU</td><td>抢占式优先级 + 轮转调度器，带 IST 栈的 256 门 IDT，100 Hz PIT + HPET/PM-timer/TSC 源，LAPIC</td></tr><tr><td>Ring 3</td><td>ELF 加载器，53 个系统调用，信号，fork/exec/pipes/select/mmap，动态链接（内置 ld.so，PIE，dlsym）</td></tr><tr><td>存储</td><td>AHCI，ATA/ATA-DMA，NVMe，virtio-blk，USB MSC，SCSI（LSI）；支持 LFN 的 FAT32，exFAT，ext4，ramfs；GPT/MBR 分区；A/B 槽位</td></tr><tr><td>网络</td><td>e1000/e1000e/igb/ixgbe/rtl8139/rtl8169-family/BCM57xx 驱动，ARP/IPv4/ICMP/UDP/DNS/TCP 与拥塞控制，套接字，防火墙，HTTPS 客户端（TLS 1.2/1.3 + X.509 链），SSH 客户端 + sshd</td></tr><tr><td>USB</td><td>UHCI，OHCI，EHCI，xHCI；海量存储、HID、串行、音频类设备</td></tr><tr><td>媒体</td><td>HDA / AC97 / SB16 / ES1370 / virtio 声卡；支持 MJPEG 的 UVC 摄像头</td></tr><tr><td>平台</td><td>ACPI（FADT/DSDT/MCFG，真实 AML 解析器，S3 挂起/恢复），Intel TCO + ACPI WDAT 硬件看门狗，HPET，i2c/SMBus</td></tr><tr><td>Shell</td><td>233 条命令，管道/重定向/通配符/环境变量/别名/脚本，两种视图的帮助（<code>-a</code>，<code>-w</code>）</td></tr><tr><td>TUI</td><td>桌面、任务栏、菜单、表单、编辑器、系统应用——外加一个中文控制台层（16x16 字体，拼音输入法）</td></tr><tr><td>可靠性</td><td>串口 + /etc crashlog 的崩溃转储，带轮转/级别/过滤器的内核日志，健康监控（CPU/内存/任务/IO + JSON 导出），带 SHA256 + 签名和回滚的 OTA</td></tr></tbody></table><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># build (Linux): needs gcc nasm xorriso mtools grub-common</span></span>
<span class="line"><span>#               grub-pc-bin grub-efi-amd64-bin zip python3</span></span>
<span class="line"><span>./build.sh iso</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run it</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># inside the guest</span></span>
<span class="line"><span>oc&gt; help -a</span></span>
<span class="line"><span>oc&gt; dhcp</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2</span></span>
<span class="line"><span>oc&gt; uname -a</span></span></code></pre></div><p>使用 UEFI 而非 BIOS：<code>make run-uefi</code>。Windows 主机：<code>build.ps1</code> （WSL2/MSYS2）。完整指南：<a href="./BUILDING.html">BUILDING.md</a>。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>每个发布版都从相同的字节可复现管道中生成三个资产——当前发布版始终在 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub 发布页面</a> 和 <a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">官网下载页面</a> 上镜像：</p><table tabindex="0"><thead><tr><th>资产</th><th>说明</th></tr></thead><tbody><tr><td><code>opencube-&lt;version&gt;.iso</code></td><td>混合 BIOS+UEFI 可启动 ISO - 在 QEMU 中启动或写入 USB</td></tr><tr><td><code>opencube-&lt;version&gt;-src.zip</code></td><td>确定性源码包（<code>git archive</code>）</td></tr><tr><td><code>opencube-&lt;version&gt;-update.tar.gz</code></td><td>OTA 更新包（SHA256 + 签名验证，A/B 槽位）</td></tr></tbody></table><p>每个发布说明都包含这三个文件的 SHA256；官网、发布版和私有镜像持有完全相同的字节副本。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li><a href="./BUILDING.html">BUILDING.md</a> - 在 Linux/Windows 上构建，QEMU， 交叉编译（ARM64/RISC-V Shell），可复现性验证</li><li><a href="./ARCHITECTURE.html">ARCHITECTURE.md</a> - L0 架构，从头到尾</li><li><a href="./INTERFACES.html">INTERFACES.md</a> - 233 条命令和 L1 接口面 （从源树生成：<code>make api-docs</code>）</li><li><a href="./FAQ.html">FAQ.md</a> - 常见问题</li><li><a href="./CONTRIBUTING.html">CONTRIBUTING.md</a> - 基本规则和 PR 合入门槛</li><li>完整文档中心（用户手册、开发者手册、 驱动点亮手册、L1 扩展指南、内部机制）： <strong><a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">https://cubestudio-dev.github.io/OpenCubeOS/docs/</a></strong></li></ul><h2 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to &quot;统计&quot;">​</a></h2><p>以下所有数字都在构建时通过机器验证 （<code>make api-docs</code> 写入 <code>docs/data/*.json</code>；README 验证命令按项目引用）：</p><ul><li><strong>源代码</strong>：140,672 行 - 内核 + 启动 + 用户程序 + 文件系统 + 网络 + Shell + l1 + 驱动 + 库 + TUI + 中文 + 架构，包含头文件， 排除 docs/tools/tests 和生成的数据块。 验证： <code>git ls-files | grep -E &#39;\\.(c|h|S)$&#39; | grep -E &#39;^(kernel|boot|userprogs|fs|net|shell|l1|drivers|libs|tui|chinese|arch)/&#39; | grep -vE &#39;userprobs_data|chinese_font_data|pinyin_data|grub_boot_data&#39; | xargs wc -l</code></li><li><strong>Shell 命令</strong>：233 - 在访客系统中通过 <code>help -a</code> 实时验证。</li><li><strong>L1 扩展接口</strong>：162 个编号（57 WP-09 + 8 + 13 + 7 + 26 + 11 + 7 + 9 + 8 + 16），外加文档化的未编号组 - 完整接口面见 <a href="./INTERFACES.html">INTERFACES.md</a>。</li><li><strong>系统调用</strong>：53 - 验证： <code>grep -c &#39;#define SYS_&#39; kernel/core/core_syscall.h</code></li><li><strong>CI</strong>：每次推送都通过 - 构建、ISO、包、主机测试和 可复现性门禁 (<code>.github/workflows/build.yml</code>)。</li></ul><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>Apache 2.0 - 见 <a href="./LICENSE.html">LICENSE</a>。每个源文件都带有 <code>SPDX-License-Identifier: Apache-2.0</code>。</p><p>版权所有 2026 cubestudio-dev &lt;cubestudio@qq.com&gt;</p>`,25)])])}const b=t(o,[["render",r]]);export{u as __pageData,b as default};
